/**
 * The entity-kind graph: every kind is described by facets — some required
 * (stream, authoring, parentage, resource), some optional (data, lifecycle,
 * canvas, catalog). Assembled in {@link ./modules.js}; engine imports derived
 * views from {@link ./index.js} and must not import `entities/` directly.
 *
 * See docs/design/entity-module-structure.md.
 */
/** Null-object data facet — kind is not a data lookup. */
export const NO_DATA = { participates: false };
/** Null-object canvas facet — kind is hidden from the explorer. */
export const NO_CANVAS = { participates: false };
/** Null-object catalog facet — kind does not appear in generated catalogs. */
export const NO_CATALOG = { participates: false };
/** Null-object lifecycle facet — kind has no pull/build TF hooks. */
export const NO_LIFECYCLE = { participates: false };
// ---------------------------------------------------------------------------
// Derivations from ResourceFacet
// ---------------------------------------------------------------------------
export function implementedResourceTypes(resource) {
    switch (resource.shape) {
        case "single":
            return [resource.resourceType];
        case "subTypes":
            return resource.rows.filter((r) => r.implemented).map((r) => r.resourceType);
        case "composite":
            return resource.members.filter((m) => m.implemented).map((m) => m.resourceType);
        case "none":
            return [];
    }
}
export function knownResourceTypes(resource) {
    switch (resource.shape) {
        case "single":
            return [resource.resourceType];
        case "subTypes":
            return resource.rows.map((r) => r.resourceType);
        case "composite":
            return resource.members.map((m) => m.resourceType);
        case "none":
            return [];
    }
}
export function isResourceAdoptable(resource) {
    switch (resource.shape) {
        case "single":
            return resource.adoptable;
        case "subTypes":
            return resource.adoptable !== false && resource.rows.some((r) => r.implemented);
        case "composite":
            return resource.adoptable;
        case "none":
            return false;
    }
}
export function defaultMatchResourceType(resource, type) {
    switch (resource.shape) {
        case "single":
            return resource.resourceType === type ? "extract" : false;
        case "subTypes": {
            const row = resource.rows.find((r) => r.resourceType === type);
            if (row === undefined)
                return false;
            return row.implemented ? "extract" : "reported";
        }
        case "composite": {
            const member = resource.members.find((m) => m.resourceType === type);
            if (member === undefined)
                return false;
            if (!member.implemented)
                return "reported";
            // Skeleton / primary member extracts; family members group with it.
            return member.role === "skeleton" ? "extract" : "family";
        }
        case "none":
            return false;
    }
}
export function matchType(module, type) {
    if (module.stream.role === "streamReported") {
        return knownResourceTypes(module.resource).includes(type) ? "reported" : false;
    }
    if (module.lifecycle.participates && module.lifecycle.matchResourceType !== undefined) {
        return module.lifecycle.matchResourceType(type);
    }
    return defaultMatchResourceType(module.resource, type);
}
/**
 * Whether this kind participates in managed resource adopt / build-vs-export resource
 * sets. Data-facet-only kinds (`authoring: none`, `orgExport`) are excluded;
 * their types enter build-vs-export via `data.referencedByBuild` instead.
 */
export function isTfLive(module) {
    return (module.stream.role !== "streamReported" &&
        module.stream.role !== "orgExport" &&
        module.authoring.unit !== "none" &&
        module.resource.shape !== "none");
}
/** Single resource type string for data-facet / single-shape kinds. */
export function singleResourceType(module) {
    return module.resource.shape === "single" ? module.resource.resourceType : undefined;
}
